:root {
  /* Colors */
  --color-paper-canvas: #ffffff;
  --color-cream-surface: #fefdfb;
  --color-linen-tile: #faf8f5;
  --color-jet-action: #08090a;
  --color-ink: #121715;
  --color-slate-caption: #485450;
  --color-pewter-muted: #717d79;
  --color-ash-whisper: #969e9b;
  --color-stone-rule: #f1f0ee;
  --color-fog-hairline: #0000000a;
  --color-smoke-ring: #0000000f;
  --color-mint-wash: #1fa77a14;
  --color-forest-ink: #0c8c5e;

  /* Typography — Font Families */
  --font-inter: "Inter", ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
  --font-paper-mono: "Paper Mono", ui-monospace, SFMono-Regular, Menlo, Monaco, Consolas, monospace;
  --font-arizona-flare: "Arizona Flare", ui-serif, Georgia, Cambria, "Times New Roman", Times, serif;

  /* Typography — Scale */
  --text-small: 12px;
  --leading-small: 1.333;
  --tracking-small: 0.24px;
  --text-caption: 12px;
  --leading-caption: 1;
  --tracking-caption: 0.24px;
  --text-body-sm: 14px;
  --leading-body-sm: 1.429;
  --tracking-body-sm: 0px;
  --text-body: 16px;
  --leading-body: 1.5;
  --tracking-body: 0px;
  --text-body-lg: 18px;
  --leading-body-lg: 1.333;
  --tracking-body-lg: 0px;
  --text-heading-sm: 24px;
  --leading-heading-sm: 1.167;
  --tracking-heading-sm: -0.24px;
  --text-heading: 36px;
  --leading-heading: 1.111;
  --tracking-heading: -0.72px;
  --text-heading-lg: 44px;
  --leading-heading-lg: 1.091;
  --tracking-heading-lg: -0.88px;
  --text-display: 50px;
  --leading-display: 1.04;
  --tracking-display: -2px;

  /* Typography — Weights */
  --font-weight-regular: 400;
  --font-weight-medium: 500;

  /* Spacing */
  --spacing-4: 4px;
  --spacing-6: 6px;
  --spacing-8: 8px;
  --spacing-10: 10px;
  --spacing-12: 12px;
  --spacing-14: 14px;
  --spacing-16: 16px;
  --spacing-20: 20px;
  --spacing-24: 24px;
  --spacing-28: 28px;
  --spacing-32: 32px;
  --spacing-40: 40px;
  --spacing-48: 48px;
  --spacing-80: 80px;
  --spacing-104: 104px;

  /* Layout */
  --layout-max-width: 1088px;
  --layout-heading-width: 664px;
  --layout-faq-width: 768px;
  --layout-section-gap: 104px;
  --layout-card-padding: 32px;
  --layout-element-gap: 16px;

  /* Border Radius */
  --radius-sm: 2px;
  --radius-md: 4px;
  --radius-lg: 6px;
  --radius-xl: 12px;
  --radius-full: 9999px;

  /* Named Radii */
  --radius-small-elements: 2px;
  --radius-buttons: 4px;
  --radius-tags: 4px;
  --radius-cards: 6px;
  --radius-inner-tiles: 12px;
  --radius-images: 12px;
  --radius-pills: 9999px;

  /* Shadows */
  --shadow-subtle: inset 0 0 0 1px rgba(0, 0, 0, 0.02);

  /* Surfaces */
  --surface-paper-canvas: #ffffff;
  --surface-linen-tile: #faf8f5;
  --surface-cream-surface: #fefdfb;
  --surface-jet-action: #08090a;
}

